// Every default is applied HERE, never assumed from the caller. Real callers send
// "" for what they did not fill, so "" is the value each branch is built around
// rather than an edge case.
def s   = (search == null) ? '' : search.toString().trim()
def stx = (status == null) ? '' : status.toString().trim()
def tid = (titleId == null) ? '' : titleId.toString().trim()
def rid = (territoryId == null) ? '' : territoryId.toString().trim()
def mid = (managerPositionId == null) ? '' : managerPositionId.toString().trim()
def raw = (asOfDate == null) ? '' : asOfDate.toString().trim()
def lim = (limit == null) ? '' : limit.toString().trim()
def off = (offset == null) ? '' : offset.toString().trim()
def org = (includeOrg == null) ? '' : includeOrg.toString().trim()

boolean valid = true
String reason = ''
long epoch = 0L
String day = ''

if (raw.isEmpty()) {
    // default: TODAY, UTC - echoed back so a caller in another timezone always
    // knows which day it actually got
    def d = java.time.LocalDate.now(java.time.ZoneOffset.UTC)
    epoch = d.atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli()
    day = d.toString()
} else if (raw ==~ /^\d{4}-\d{2}-\d{2}$/) {
    try {
        def d = java.time.LocalDate.parse(raw)
        epoch = d.atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli()
        day = raw
    } catch (Exception e) { valid = false; reason = 'asOfDate is not a real calendar date: ' + raw }
} else if (raw ==~ /^\d{9,}$/) {
    epoch = Long.parseLong(raw)
    day = java.time.Instant.ofEpochMilli(epoch).atZone(java.time.ZoneOffset.UTC).toLocalDate().toString()
} else {
    valid = false; reason = 'asOfDate must be YYYY-MM-DD or epoch milliseconds, got: ' + raw
}

int pageLimit = 50
if (!lim.isEmpty()) {
    if (lim ==~ /^\d+$/) { pageLimit = Integer.parseInt(lim) } else { valid = false; reason = 'limit must be a whole number, got: ' + lim }
}
if (pageLimit < 1) pageLimit = 1
if (pageLimit > 200) pageLimit = 200

int pageOffset = 0
if (!off.isEmpty()) {
    if (off ==~ /^\d+$/) { pageOffset = Integer.parseInt(off) } else { valid = false; reason = 'offset must be a whole number, got: ' + off }
}

boolean wantOrg = org.isEmpty() ? true : !(org.equalsIgnoreCase('false'))
boolean wantTitle = !tid.isEmpty()
boolean wantTerr  = !rid.isEmpty()
boolean wantMgr   = !mid.isEmpty()
boolean restrict  = wantTitle || wantTerr || wantMgr

// The INVERSION. titleId / territoryId / managerPositionId do not live on Payee -
// they hang off effective-dated rows on the position a payee holds. Filtering them
// after the page is fetched would make 'total' count rows the caller cannot see and
// 'hasMore' lie, which on a scroll-paged table shows a short page and stops. So the
// matching POSITIONS are resolved first and become an 'id IN' on the Payee fetch.
// When no org filter was sent these two fetches are sentinel no-ops.
def attrFilters = []
if (valid && (wantTitle || wantTerr)) {
    if (wantTitle) attrFilters << [property: 'properties.titleId', filter: [operator: 'EQUAL', value: tid]]
    if (wantTerr)  attrFilters << [property: 'properties.territoryId', filter: [operator: 'EQUAL', value: rid]]
    attrFilters << [property: 'properties.effectiveStart', filter: [operator: 'LTE', value: epoch]]
} else {
    attrFilters << [property: 'id', filter: [operator: 'EQUAL', value: '__none__']]
}

def hierFilters = []
if (valid && wantMgr) {
    hierFilters << [property: 'properties.parentPositionId', filter: [operator: 'EQUAL', value: mid]]
    hierFilters << [property: 'properties.effectiveStart', filter: [operator: 'LTE', value: epoch]]
} else {
    hierFilters << [property: 'id', filter: [operator: 'EQUAL', value: '__none__']]
}

// ---------------------------------------------------------------------------
// The condition list. Every operator below is built into the STORE filter, so
// the page that comes back is already the answer: nothing is filtered after the
// fetch, which is what keeps 'total' and 'hasMore' honest.
//
// The store has no NOT group and no "not contains" leaf, so NCONTAINS cannot be
// expressed directly. It is turned into an id set by a pre-pass instead - the
// ids that DO contain the term - and applied here as 'id NOT_IN'.
// ---------------------------------------------------------------------------
def PROP = [employeeId: 'properties.employeeId', name: 'properties.name',
            email: 'properties.email', status: 'properties.status']
def TEXTS = ['properties.employeeId', 'properties.name', 'properties.email']

// Escape the metacharacters so a name with a dot cannot become a wildcard.
// Written WITHOUT a single backslash: this source travels through a JS template
// literal on the way here, which eats one level of escaping, and the version
// that did use them arrived as invalid Groovy ("Unexpected character"). 92 is
// the backslash codepoint.
def META = '.[]{}()*+?^$|'
def rx = { String v ->
    def sb = new StringBuilder()
    for (int i = 0; i < v.length(); i++) {
        char ch = v.charAt(i)
        if (META.indexOf((int) ch) >= 0 || ((int) ch) == 92) sb.append((char) 92)
        sb.append(ch)
    }
    return sb.toString()
}

def leaf = { String prop, String op, def v ->
    def sv = (v == null) ? '' : String.valueOf(v)
    if (op == 'EQ')        return [property: prop, filter: [operator: 'EQUAL', value: sv]]
    if (op == 'NEQ')       return [property: prop, filter: [operator: 'NOT_EQUAL', value: sv]]
    if (op == 'CONTAINS')  return [property: prop, filter: [operator: 'ICONTAINS', value: sv]]
    if (op == 'STARTS')    return [property: prop, filter: [operator: 'STARTS_WITH', value: sv]]
    // no ENDS_WITH leaf exists; REGEX is the only way to anchor at the end
    if (op == 'ENDS')      return [property: prop, filter: [operator: 'REGEX', value: '.*' + rx(sv) + '$']]
    // Probed on tool 2026-09-07, both the obvious choices are dead ends:
    // EXISTS/MISSING are INVERTED on these string properties (MISSING matched all
    // 16 payees, EXISTS matched none), and MIN_LENGTH is rejected outright as
    // "Invalid filter operator" by the storage node even though the ops list
    // names it. REGEX is the one that works - '.+' is "has at least one character".
    if (op == 'NEMPTY')    return [property: prop, filter: [operator: 'REGEX', value: '.+']]
    if (op == 'IN' || op == 'NIN') {
        def list = (v instanceof List) ? v.collect { String.valueOf(it) }
                                       : sv.split(',').collect { it.trim() }.findAll { !it.isEmpty() }
        // An empty IN list reads as "no filter" to the store, which would widen the
        // result instead of narrowing it. The sentinel keeps it an empty match.
        if (list.isEmpty()) list = ['__none__']
        return [property: prop, filter: [operator: (op == 'IN' ? 'IN' : 'NOT_IN'), value: list]]
    }
    return null
}

def condLeaves = []
def ncTerms = []
def ncLeafFilters = []
// A caller that predates these inputs does not send them at all, and an unsent
// parameter is UNBOUND in a code node - not null. Reading it directly throws
// "No such property", which is exactly how the existing suite broke. Ask the
// binding first so the older contract keeps working untouched.
def filtersIn = binding.hasVariable('filters') ? filters : null
def combIn = binding.hasVariable('combinator') ? combinator : null
def rowsIn = (filtersIn instanceof List) ? filtersIn : []
rowsIn.each { c ->
    def f  = String.valueOf(c?.field == null ? '' : c.field).trim()
    def op = String.valueOf(c?.op == null ? '' : c.op).trim().toUpperCase()
    def v  = c?.value
    if (f.isEmpty() || op.isEmpty()) return
    // A blank value is an incomplete row, not a filter for blank - except for the
    // two operators that are ABOUT blankness.
    if (op != 'EMPTY' && op != 'NEMPTY' && (v == null || String.valueOf(v).trim().isEmpty())) return

    if (f == 'search') {
        // one clause across all three text fields
        if (op == 'NCONTAINS') {
            ncTerms << [mode: 'contains', term: String.valueOf(v), props: TEXTS]
            TEXTS.each { pr -> ncLeafFilters << [property: pr, filter: [operator: 'ICONTAINS', value: String.valueOf(v)]] }
        } else {
            def group = []
            TEXTS.each { pr -> def l = leaf(pr, op, v); if (l != null) group << l }
            if (!group.isEmpty()) condLeaves << [operator: 'OR', filters: group]
        }
        return
    }

    def prop = PROP[f]
    if (prop == null) { valid = false; reason = 'unknown filter field: ' + f; return }

    if (op == 'NCONTAINS') {
        ncTerms << [mode: 'contains', term: String.valueOf(v), props: [prop]]
        ncLeafFilters << [property: prop, filter: [operator: 'ICONTAINS', value: String.valueOf(v)]]
        return
    }
    // "is empty" is the negation of "has any value", and there is no NOT group -
    // so it resolves through the same pre-pass as NCONTAINS.
    if (op == 'EMPTY') {
        ncTerms << [mode: 'nonempty', term: '', props: [prop]]
        ncLeafFilters << [property: prop, filter: [operator: 'REGEX', value: '.+']]
        return
    }
    def l = leaf(prop, op, v)
    if (l == null) { valid = false; reason = 'unknown filter operator: ' + op; return }
    condLeaves << l
}

String combine = (combIn == null) ? '' : combIn.toString().trim().toUpperCase()
if (combine != 'OR') combine = 'AND'

// An OR cannot mix CASE-INSENSITIVE leaves with CASE-SENSITIVE ones. It does not
// error - it quietly answers zero rows, which reads as "no matches" and is the
// worst shape a filter bug can take. Probed on tool 2026-09-07, 12 pairs:
//
//   ICONTAINS + ICONTAINS   ok      ICONTAINS + STARTS_WITH  ZERO
//   REGEX     + ICONTAINS   ok      ICONTAINS + EQUAL        ZERO
//   EQUAL     + STARTS_WITH ok      ICONTAINS + NOT_IN       ZERO
//   EQUAL     + IN          ok      REGEX     + STARTS_WITH  ZERO
//   STARTS_WITH + IN        ok      REGEX     + EQUAL        ZERO
//
// The operators themselves are not the axis - EQUAL ORs happily with STARTS_WITH,
// and ICONTAINS with REGEX. What never survives is one of each CLASS. ICONTAINS
// and REGEX are matched case-insensitively; every other operator compares exactly.
//
// Counted over the leaves the CONSUMER will build, not the ones visible here:
// every ncTerm becomes one more leaf downstream ('id NOT_IN <hits>'), which is
// case-sensitive and joins this same OR.
def CI_OPS = ['ICONTAINS', 'REGEX'] as Set
boolean memMode = false
if (combine == 'OR' && (condLeaves.size() + ncTerms.size()) > 1) {
    def classes = [] as Set
    // A nested group contributes its MEMBERS, not an opaque kind of its own. The
    // search clause is an OR of three ICONTAINS, so OR[searchGroup, ICONTAINS] is
    // the same query as a flat OR of four - which is proven to work. Treating the
    // group as its own class would refuse 'Person OR Name', the pairing this
    // panel is most likely to be asked for.
    condLeaves.each { l ->
        if (l.containsKey('filter')) {
            classes << (CI_OPS.contains(String.valueOf(l.filter.operator)) ? 'ci' : 'cs')
        } else if (l.filters != null) {
            l.filters.each { m ->
                classes << (CI_OPS.contains(String.valueOf(m?.filter?.operator)) ? 'ci' : 'cs')
            }
        }
    }
    if (!ncTerms.isEmpty()) classes << 'cs'
    // Rather than refuse the query, resolve it OURSELVES. The store cannot OR
    // across the two classes, but it CAN hand back a superset in one call: every
    // positive condition is a subset of the same term matched case-insensitively,
    // and a homogeneous case-insensitive OR is proven to work. The conditions are
    // then applied exactly in memory and the whole OR collapses to a single
    // 'id IN <matched>' leaf - one leaf, so there is nothing left to mix.
    //
    // It costs the pre-pass fetch that 'does not contain' already pays for, and
    // it is the same machinery: n_FtNc's filter simply becomes the superset.
    if (classes.size() > 1) memMode = true
}

// Every condition, in the shape the in-memory evaluator wants. Built only for
// the mixed case; the store answers everything else directly and faster.
def memTerms = []
def memFilters = []
boolean memScanAll = false
if (memMode) {
    // NEGATIVE operators match almost everything, so no term-based superset can
    // bound them - those force a full scan of the candidate set.
    def NEGATIVE = ['NEQ', 'NIN', 'NCONTAINS', 'EMPTY'] as Set
    rowsIn.each { c ->
        def f  = String.valueOf(c?.field == null ? '' : c.field).trim()
        def op = String.valueOf(c?.op == null ? '' : c.op).trim().toUpperCase()
        def v  = c?.value
        if (f.isEmpty() || op.isEmpty()) return
        if (op != 'EMPTY' && op != 'NEMPTY' && (v == null || String.valueOf(v).trim().isEmpty())) return
        def props = (f == 'search') ? TEXTS : (PROP[f] == null ? null : [PROP[f]])
        if (props == null) return
        def vals = (v instanceof List) ? v.collect { String.valueOf(it) } : [String.valueOf(v)]
        memTerms << [props: props, op: op, values: vals]

        if (NEGATIVE.contains(op)) { memScanAll = true; return }
        if (op == 'NEMPTY') {
            props.each { pr -> memFilters << [property: pr, filter: [operator: 'REGEX', value: '.+']] }
        } else {
            // EQ / IN / CONTAINS / STARTS / ENDS are all subsets of the same
            // text matched case-insensitively.
            props.each { pr ->
                vals.each { val ->
                    memFilters << [property: pr, filter: [operator: 'ICONTAINS', value: val]]
                }
            }
        }
    }
    // Nothing survived as a bound, so ask for the candidate set unfiltered. An
    // AND with no filters is the store's "everything" - the same shape the
    // blank-payload path already relies on.
    if (memScanAll || memFilters.isEmpty()) memFilters = []
    condLeaves = []
    ncTerms = []
}

// The pre-pass fetch for every NCONTAINS term at once - one call however many
// negations were sent, rather than one per condition.
// In the mixed-OR case this same fetch carries the SUPERSET instead - the two
// never coexist, because memMode clears ncTerms.
def ncFilter
if (memMode) {
    ncFilter = memFilters.isEmpty() ? [operator: 'AND', filters: []]
                                    : [operator: 'OR', filters: memFilters]
} else if (ncLeafFilters.isEmpty()) {
    ncFilter = [operator: 'AND', filters: [[property: 'id', filter: [operator: 'EQUAL', value: '__none__']]]]
} else {
    ncFilter = [operator: 'OR', filters: ncLeafFilters]
}

return [condLeaves: condLeaves, ncTerms: ncTerms, ncFilter: ncFilter,
        memMode: memMode, memTerms: memTerms,
        combine: combine, hasConds: (!condLeaves.isEmpty() || !ncTerms.isEmpty() || memMode),
        valid: valid, reason: reason, asOfEpoch: epoch, asOfDay: day,
        pageLimit: pageLimit, pageOffset: pageOffset, wantOrg: wantOrg,
        restrict: restrict, wantTitle: wantTitle, wantTerr: wantTerr, wantMgr: wantMgr,
        searchText: s, statusText: stx.toUpperCase(),
        attrFilter: [operator: 'AND', filters: attrFilters],
        hierFilter: [operator: 'AND', filters: hierFilters]]

def inForce = { p, long asOf ->
    def st = p?.effectiveStart
    def en = p?.effectiveEnd
    boolean started = (st == null) || (Long.valueOf(String.valueOf(st)) <= asOf)
    boolean open = (en == null) || en.toString().trim().isEmpty()
    return started && (open || Long.valueOf(String.valueOf(en)) >= asOf)
}

long asOf = Long.valueOf(String.valueOf(asOfEpoch))
def attrPos = []
if (attrRows != null) attrRows.each { r ->
    if (inForce(r.properties, asOf)) {
        def k = String.valueOf(r.properties?.positionId)
        if (!attrPos.contains(k)) attrPos << k
    }
}
def hierPos = []
if (hierRows != null) hierRows.each { r ->
    if (inForce(r.properties, asOf)) {
        def k = String.valueOf(r.properties?.positionId)
        if (!hierPos.contains(k)) hierPos << k
    }
}
// Two filters together mean the INTERSECTION, never the union - somebody asking for
// one territory under one manager wants the overlap.
def ids = null
if ((wantTitle as boolean) || (wantTerr as boolean)) ids = attrPos
if (wantMgr as boolean) ids = (ids == null) ? hierPos : ids.findAll { hierPos.contains(it) }
if (ids == null) ids = []

// An empty IN list means "no filter" to the store, which here would show every
// person in the company to somebody who asked for one territory. The sentinel
// keeps an empty match an empty result.
def useIds = ids.isEmpty() ? ['__none__'] : ids
return [positionIds: useIds, matched: ids.size(),
        filter: [operator: 'AND', filters: [
            [property: 'properties.positionId',     filter: [operator: 'IN',  value: useIds]],
            [property: 'properties.effectiveStart', filter: [operator: 'LTE', value: asOf]]]]]

long asOf = Long.valueOf(String.valueOf(asOfEpoch))
def ids = []
if (asgRows != null) asgRows.each { r ->
    def p = r.properties
    def en = p?.effectiveEnd
    boolean open = (en == null) || en.toString().trim().isEmpty()
    if (open || Long.valueOf(String.valueOf(en)) >= asOf) {
        def pid = (p?.payeeId == null) ? '' : p.payeeId.toString().trim()
        if (!pid.isEmpty() && !ids.contains(pid)) ids << pid
    }
}

// Turn each negated term into an exclusion. The pre-pass returned everyone who
// DOES match; a term that matched nobody excludes nobody, which is why the
// sentinel is used rather than an empty NOT_IN.
def ncLeaves = []
if (ncTerms != null) ncTerms.each { t ->
    def term = String.valueOf(t.term).toLowerCase()
    def hitIds = []
    if (ncRows != null) ncRows.each { r ->
        def p = r.properties
        boolean hit = false
        def mode = String.valueOf(t.mode == null ? 'contains' : t.mode)
        t.props.each { pr ->
            def key = String.valueOf(pr).replace('properties.', '')
            def val = p == null ? null : p[key]
            if (mode == 'nonempty') {
                if (val != null && !val.toString().trim().isEmpty()) hit = true
            } else if (val != null && val.toString().toLowerCase().contains(term)) {
                hit = true
            }
        }
        if (hit) hitIds << String.valueOf(r.id)
    }
    ncLeaves << [property: 'id', filter: [operator: 'NOT_IN',
                 value: hitIds.isEmpty() ? ['__none__'] : hitIds]]
}

def userLeaves = []
if (condLeaves != null) userLeaves.addAll(condLeaves)
userLeaves.addAll(ncLeaves)

// The mixed-OR path. The store cannot OR a case-insensitive leaf with a
// case-sensitive one, so the whole condition list is applied HERE against the
// superset n_FtNc returned, and leaves as a single 'id IN <matched>' - which has
// no operator to disagree with. Same answer, one extra fetch, no refusal.
boolean memTruncated = false
if (memMode as boolean) {
    def NEG = ['NEQ': 'EQ', 'NIN': 'IN', 'NCONTAINS': 'CONTAINS', 'EMPTY': 'NEMPTY']
    def hitIds = []
    if (ncRows != null) ncRows.each { r ->
        def p = r.properties
        boolean any = false
        if (memTerms != null) memTerms.each { t ->
            if (any) return
            String op = String.valueOf(t.op)
            boolean negate = NEG.containsKey(op)
            String base = negate ? String.valueOf(NEG[op]) : op
            boolean hit = false
            t.props.each { pr ->
                if (hit) return
                def key = String.valueOf(pr).replace('properties.', '')
                def raw = (p == null) ? null : p[key]
                String val = (raw == null) ? '' : String.valueOf(raw)
                String lo = val.toLowerCase()
                if (base == 'NEMPTY')       { if (!val.trim().isEmpty()) hit = true }
                else if (base == 'EQ')      { t.values.each { v -> if (val == String.valueOf(v)) hit = true } }
                else if (base == 'IN')      { t.values.each { v -> if (val == String.valueOf(v)) hit = true } }
                else if (base == 'CONTAINS'){ t.values.each { v -> if (lo.contains(String.valueOf(v).toLowerCase())) hit = true } }
                else if (base == 'STARTS')  { t.values.each { v -> if (val.startsWith(String.valueOf(v))) hit = true } }
                else if (base == 'ENDS')    { t.values.each { v -> if (lo.endsWith(String.valueOf(v).toLowerCase())) hit = true } }
            }
            // A negation over several properties means NONE of them matched -
            // 'name does not contain X' is false the moment one field holds X.
            if (negate ? !hit : hit) any = true
        }
        if (any) hitIds << String.valueOf(r.id)
    }
    // 2000 is the fetch cap. At the cap the superset may have been cut off, and a
    // filter that silently drops matches is the very thing this path exists to
    // avoid - so it is reported rather than swallowed.
    memTruncated = (ncRows != null && ncRows.size() >= 2000)
    userLeaves = [[property: 'id', filter: [operator: 'IN',
                   value: hitIds.isEmpty() ? ['__none__'] : hitIds]]]
}

def s = (searchText == null) ? '' : searchText.toString().trim()
def st = (statusText == null) ? '' : statusText.toString().trim()

def filters = []
if (!(valid as boolean)) {
    filters << [property: 'id', filter: [operator: 'EQUAL', value: '__invalid_input__']]
} else {
    // The condition list combines by the caller's AND/OR. The legacy scalar
    // inputs always AND on top, so an older caller sending only those keeps the
    // behaviour it was written against.
    if (!userLeaves.isEmpty()) {
        filters << (userLeaves.size() == 1 ? userLeaves[0]
                                           : [operator: String.valueOf(combine), filters: userLeaves])
    }
    if (!s.isEmpty()) filters << [operator: 'OR', filters: [
        [property: 'properties.employeeId', filter: [operator: 'ICONTAINS', value: s]],
        [property: 'properties.name',       filter: [operator: 'ICONTAINS', value: s]],
        [property: 'properties.email',      filter: [operator: 'ICONTAINS', value: s]]]]
    if (!st.isEmpty()) filters << [property: 'properties.status', filter: [operator: 'EQUAL', value: st]]
    if (restrict as boolean) filters << [property: 'id', filter: [operator: 'IN', value: ids.isEmpty() ? ['__none__'] : ids]]
}
return [payeeIds: ids, restricted: (restrict as boolean), memTruncated: memTruncated,
        filter: [operator: 'AND', filters: filters]]

long asOf = Long.valueOf(String.valueOf(asOfEpoch))
def live = []
def posIds = []
if (rows != null) rows.each { r ->
    def p = r.properties
    def en = p?.effectiveEnd
    boolean open = (en == null) || en.toString().trim().isEmpty()
    if (open || Long.valueOf(String.valueOf(en)) >= asOf) {
        def pos = String.valueOf(p?.positionId)
        // carry the window and the split through: the fold needs them for an
        // ASSIGNED row, and re-fetching them later would be a second call for
        // data already in hand
        live << [payeeId: String.valueOf(p?.payeeId), positionId: pos,
                 effectiveStart: (p?.effectiveStart == null) ? null : Long.valueOf(String.valueOf(p.effectiveStart)),
                 effectiveEnd:   (en == null || en.toString().trim().isEmpty()) ? null : Long.valueOf(String.valueOf(en)),
                 allocationPct:  (p?.allocationPct == null) ? null : Double.valueOf(String.valueOf(p.allocationPct))]
        if (!posIds.contains(pos)) posIds << pos
    }
}
def usePos = posIds.isEmpty() ? ['__none__'] : posIds
return [live: live, positionIds: usePos,
        filter: [operator: 'AND', filters: [
            [property: 'properties.positionId',     filter: [operator: 'IN',  value: usePos]],
            [property: 'properties.effectiveStart', filter: [operator: 'LTE', value: asOf]]]]]

def inForce = { p, long asOf ->
    def st = p?.effectiveStart
    def en = p?.effectiveEnd
    boolean started = (st == null) || (Long.valueOf(String.valueOf(st)) <= asOf)
    boolean open = (en == null) || en.toString().trim().isEmpty()
    return started && (open || Long.valueOf(String.valueOf(en)) >= asOf)
}

long asOf = Long.valueOf(String.valueOf(asOfEpoch))
def parentByPos = [:]
def parents = []
if (hierRows != null) hierRows.each { r ->
    def p = r.properties
    if (inForce(p, asOf)) {
        def k = String.valueOf(p?.positionId)
        // several in force is a data problem, not a pick - keep the first
        if (!parentByPos.containsKey(k)) {
            def par = String.valueOf(p?.parentPositionId)
            parentByPos[k] = par
            if (!parents.contains(par)) parents << par
        }
    }
}
// One Position fetch covers the page's own seats AND their managers' seats.
def all = []
if (positionIds != null) positionIds.each { if (it != '__none__' && !all.contains(it)) all << it }
parents.each { if (!all.contains(it)) all << it }
def useAll = all.isEmpty() ? ['__none__'] : all
def useParents = parents.isEmpty() ? ['__none__'] : parents

return [parentByPos: parentByPos, parentIds: useParents,
        posFilter: [operator: 'AND', filters: [
            [property: 'id', filter: [operator: 'IN', value: useAll]]]],
        mgrFilter: [operator: 'AND', filters: [
            [property: 'properties.positionId',     filter: [operator: 'IN',  value: useParents]],
            [property: 'properties.effectiveStart', filter: [operator: 'LTE', value: asOf]]]]]

long asOf = Long.valueOf(String.valueOf(asOfEpoch))
def mgrLive = []
def ids = []
if (rows != null) rows.each { r ->
    def p = r.properties
    def en = p?.effectiveEnd
    boolean open = (en == null) || en.toString().trim().isEmpty()
    if (open || Long.valueOf(String.valueOf(en)) >= asOf) {
        def pid = (p?.payeeId == null) ? '' : p.payeeId.toString().trim()
        mgrLive << [positionId: String.valueOf(p?.positionId), payeeId: pid]
        if (!pid.isEmpty() && !ids.contains(pid)) ids << pid
    }
}
def useIds = ids.isEmpty() ? ['__none__'] : ids
return [mgrLive: mgrLive,
        filter: [operator: 'AND', filters: [[property: 'id', filter: [operator: 'IN', value: useIds]]]]]

def inForce = { p, long asOf ->
    def st = p?.effectiveStart
    def en = p?.effectiveEnd
    boolean started = (st == null) || (Long.valueOf(String.valueOf(st)) <= asOf)
    boolean open = (en == null) || en.toString().trim().isEmpty()
    return started && (open || Long.valueOf(String.valueOf(en)) >= asOf)
}

long asOf = Long.valueOf(String.valueOf(asOfEpoch))

def byPayee = [:]
if (live != null) live.each { l ->
    def k = String.valueOf(l.payeeId)
    if (!byPayee.containsKey(k)) byPayee[k] = []
    byPayee[k] << l
}
def posById = [:]
if (posRows != null) posRows.each { p -> posById[String.valueOf(p.id)] = p.properties }
def titleById = [:]
if (titleRows != null) titleRows.each { t -> titleById[String.valueOf(t.id)] = t.properties?.name ?: '' }
def terrById = [:]
if (terrRows != null) terrRows.each { t -> terrById[String.valueOf(t.id)] = t.properties?.name ?: '' }
def mgrPayById = [:]
if (mgrPayRows != null) mgrPayRows.each { p -> mgrPayById[String.valueOf(p.id)] = p.properties?.name ?: '' }

// A seat's title is effective-dated too: an attribute row that ended before the
// date describes a seat that has since been re-titled.
def attrByPos = [:]
if (attrRows != null) attrRows.each { a ->
    def ap = a.properties
    if (inForce(ap, asOf)) {
        def k = String.valueOf(ap?.positionId)
        if (!attrByPos.containsKey(k)) attrByPos[k] = ap
    }
}
def mgrByPos = [:]
if (mgrLive != null) mgrLive.each { m ->
    def k = String.valueOf(m.positionId)
    if (!mgrByPos.containsKey(k)) mgrByPos[k] = []
    mgrByPos[k] << m
}

def eligByPayee = [:]
int eligConflict = 0
if (eligRows != null) eligRows.each { e ->
    if (!inForce(e.properties, asOf)) return
    def k = String.valueOf(e.properties?.payeeId)
    if (eligByPayee.containsKey(k)) { eligConflict = eligConflict + 1; return }
    eligByPayee[k] = e
}

int assigned = 0, unassigned = 0, conflict = 0
def profiles = []
if (payRows != null) payRows.each { r ->
    def p = r.properties
    def row = [payeeId: String.valueOf(r.id),
               employeeId: p?.employeeId ?: '',
               name: p?.name ?: '',
               email: p?.email ?: '',
               status: p?.status ?: '',
               hireDate: (p?.hireDate == null) ? null : Long.valueOf(String.valueOf(p.hireDate)),
               terminationDate: (p?.terminationDate == null) ? null : Long.valueOf(String.valueOf(p.terminationDate)),
               // A person with NO row in force resolves to eligible. Every person on prod
               // has no row today, so defaulting to false would tell the app that nobody in
               // the company is on a variable plan - a total, silent change to every screen
               // caused by adding a table rather than by any decision. Absence means nothing
               // has been said, and the standing answer is eligible.
               // `!= false` and not `== true`: a boolean the platform never set is MISSING,
               // not false, so a row saved without the flag must not make someone ineligible.
               commissionEligible: (eligByPayee[String.valueOf(r.id)] == null) ? true
                   : (eligByPayee[String.valueOf(r.id)].properties?.isCommissionEligible != false),
               eligibilityReason: (eligByPayee[String.valueOf(r.id)] == null) ? ''
                   : (eligByPayee[String.valueOf(r.id)].properties?.reason ?: ''),
               assignment: 'UNKNOWN', matchCount: 0,
               positionId: '', positionCode: '', positionName: '',
               titleId: '', titleName: '', territoryId: '', territoryName: '',
               managerPositionId: '', managerPayeeId: '', managerName: '',
               // null unless ONE assignment resolved this row - an UNASSIGNED row has
               // none and a CONFLICT row has several, and naming one would be the
               // guess this product refuses to make
               allocationPct: null, effectiveStart: null, effectiveEnd: null]

    if (wantOrg) {
        def hits = byPayee[String.valueOf(r.id)] ?: []
        row.matchCount = hits.size()
        if (hits.size() == 0)     { row.assignment = 'UNASSIGNED'; unassigned++ }
        else if (hits.size() > 1) { row.assignment = 'CONFLICT';   conflict++ }
        else {
            row.assignment = 'ASSIGNED'; assigned++
            def pos = String.valueOf(hits[0].positionId)
            row.positionId = pos
            def pr = posById[pos]
            row.positionCode = (pr == null) ? '' : (pr.positionCode ?: '')
            row.positionName = (pr == null) ? '' : (pr.name ?: '')
            row.effectiveStart = hits[0].effectiveStart
            // null here means OPEN-ENDED, still held - not "unknown"
            row.effectiveEnd   = hits[0].effectiveEnd
            row.allocationPct  = hits[0].allocationPct

            def attr = attrByPos[pos]
            if (attr != null) {
                row.titleId     = (attr.titleId == null) ? '' : String.valueOf(attr.titleId)
                row.titleName   = titleById[row.titleId] ?: ''
                row.territoryId = (attr.territoryId == null) ? '' : String.valueOf(attr.territoryId)
                row.territoryName = terrById[row.territoryId] ?: ''
            }
            def par = parentByPos == null ? null : parentByPos[pos]
            if (par != null) {
                row.managerPositionId = String.valueOf(par)
                def mh = mgrByPos[String.valueOf(par)] ?: []
                // exactly as with the payee's own seat: two people in the manager
                // seat on one day is a conflict, and it is left unnamed rather than
                // guessed
                if (mh.size() == 1) {
                    row.managerPayeeId = String.valueOf(mh[0].payeeId)
                    row.managerName = mgrPayById[row.managerPayeeId] ?: ''
                }
            }
        }
    }
    profiles << row
}

int total = (payTotal == null) ? profiles.size() : Integer.valueOf(String.valueOf(payTotal))
int got   = (asgRows == null) ? 0 : asgRows.size()
int asgTot = (asgTotal == null) ? got : Integer.valueOf(String.valueOf(asgTotal))

return [profiles: profiles,
        total: total,
        hasMore: (Integer.valueOf(String.valueOf(pageOffset)) + profiles.size()) < total,
        counts: [total: profiles.size(), assigned: assigned, unassigned: unassigned, conflict: conflict],
        joinsTruncated: got < asgTot,
        message: wantOrg
            ? (profiles.size() + ' profile(s) on this page, as of ' + String.valueOf(asOfDay))
            : (profiles.size() + ' profile(s) on this page; org not resolved')]
